// Normaliza o lead do formulário "Avaliação Full Face – Qualificado"
const d = $json.data || {};
const entries = Object.entries(d).map(([k, v]) => [String(k).toLowerCase(), Array.isArray(v) ? v.join(', ') : String(v ?? '')]);
const pick = (...keys) => {
  for (const [k, v] of entries) if (keys.some(s => k.includes(s))) return v;
  return '';
};

const nome = pick('full_name', 'nome');
let telefone = pick('phone', 'telefone', 'whatsapp').replace(/\D/g, '');
if (telefone && !telefone.startsWith('55')) telefone = '55' + telefone;

const melhorar = pick('melhorar');
const regiao = pick('regi');
const quando = pick('quando', 'come');
const avaliacao = pick('avalia', 'r$', '200', 'agendar');
const incomoda = pick('incomoda', 'palavras');

const t = s => s.toLowerCase();
let prioridade = 'MORNO';
if (t(avaliacao).includes('não no momento') || t(quando).includes('pesquisando') || t(regiao).includes('fora')) prioridade = 'FRIO';
else if (t(avaliacao).includes('quero agendar') && t(quando).includes('30 dias')) prioridade = 'QUENTE';

return {
  lead_id: $json.id || '',
  data_cadastro: new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
  nome,
  primeiro_nome: nome.split(' ')[0] || '',
  telefone,
  melhorar,
  regiao,
  quando,
  avaliacao_200: avaliacao,
  o_que_incomoda: incomoda,
  prioridade,
  anuncio: ($json.ad && $json.ad.name) || '',
  status: 'NOVO',
  mensagem_enviada: '',
};

